    "content": "Trường THPT Hưng Đạo đã hợp đồng với nhà cung cấp dịch vụ (ISP) để trao đổi thông tin qua Internet. Để phụ huynh và học sinh thuận tiện cập nhật thông tin của nhà trường như thời khóa biểu, kết quả học tập của học sinh,… nhà trường đã xây dựng một website bằng phần mềm mobirise – phần mềm này là phần mềm có thể cài đặt trên nhiều hệ điều hành như Windows, MacOS, Linux,… và sử dụng mà không cần trả phí, cung cấp các mẫu thiết kế tạo sẵn cho các trang web với phần văn bản và hình ảnh được định dạng, sắp xếp theo từng chủ đề.\n\nSau khi tìm hiểu về phần mềm Mobirise một số học sinh đã đưa ra các nhận định về phần mềm trên như sau:",
