    "topicId": "tin-chuyen-de-12e-web",
    "topicName": "Chuyên đề 12E: Thực hành phần mềm tạo trang web",
    "chapterName": "Chủ đề 4: Tạo trang web với phần mềm và HTML/CSS (Tuần 12 – 20)",
    "type": "true_false",
    "content": "Trước đây, các website thường do các lập trình viên chuyên nghiệp tạo lập. Ngày nay, không cần có kĩ năng lập trình, ta cũng có thể tạo được trang web chỉ với các thao tác kéo thả đơn giản. Bằng cách sử dụng các công cụ trực quan của phần mềm tạo website Mobirise, người dùng có thể tạo, chỉnh sửa và xuất bản một website từ các mẫu hoặc các thành phần được cung cấp sẵn. Theo em, phần mềm Mobirise có những tính năng như thế nào?",
    "tfItems": [
      {
        "id": "a",
        "content": "Mobirise là phần mềm có thể cài đặt trên nhiều hệ điều hành như Windows, MacOS, Linux.",
        "correctAnswer": true
      },
      {
        "id": "b",
        "content": "Phần mềm Mobirise cung cấp các mẫu thiết kế tạo sẵn cho các trang web với phần văn bản và hình ảnh được định dạng, sắp xếp theo từng chủ đề.",
        "correctAnswer": true
      },
      {
        "id": "c",
        "content": "Chỉ có thể tạo được các trang web bằng cách viết mã lệnh.",
        "correctAnswer": false
      },
      {
        "id": "d",
        "content": "Có thể xuất bản website trực tiếp trên Internet dưới một tên miền con của mobirise.com mà không cần đăng kí tên miền riêng.",
        "correctAnswer": true
      }
    ],
    "difficulty": "ThongHieu",
    "hints": {
      "level1_concept": "Nắm vững lý thuyết xây dựng website bằng phần mềm trực quan: menu tối đa 3 cấp, header/footer đồng nhất, các khối block, form thu thập dữ liệu, hosting và tên miền.",
      "level2_formula": "Đối chiếu từng mệnh đề a, b, c, d với các nguyên tắc kỹ thuật và tính tương thích trên đa thiết bị (responsive).",
      "level3_steps": "Xác định tính Đúng / Sai của từng mệnh đề dựa trên các phát biểu chuẩn xác trong sách giáo khoa và tài liệu chuyên đề."
    },
    "explanation": "**Phân tích chi tiết từng mệnh đề cho Câu 8:**\n- **Ý a) [Đúng]**: Mobirise là phần mềm có thể cài đặt trên nhiều hệ điều hành như Windows, MacOS, Linux.\n- **Ý b) [Đúng]**: Phần mềm Mobirise cung cấp các mẫu thiết kế tạo sẵn cho các trang web với phần văn bản và hình ảnh được định dạng, sắp xếp theo từng chủ đề.\n- **Ý c) [Sai]**: Chỉ có thể tạo được các trang web bằng cách viết mã lệnh.\n- **Ý d) [Đúng]**: Có thể xuất bản website trực tiếp trên Internet dưới một tên miền con của mobirise.com mà không cần đăng kí tên miền riêng.",
    "sourceDocId": "1xB2B3HCvk32TGfYitSygKHHjhLF_S2OA",
    "sourceDocTitle": "Chuyên đề 12E. Thực hành phần mềm tạo trang web.docx (Google Drive)"
