    "type": "true_false",
    "content": "Để xây dựng văn hóa đọc cho các bạn học sinh, nhà trường có tổ chức một câu lạc bộ đọc sách và giao cho ban điều hành xây dựng website đưa thông tin về hoạt động của câu lạc bộ. Một số yêu cầu đối với website: tại trang chủ có tiêu đề “Sách hay hàng tháng, tiếp đó là hình ảnh trang bìa của khoảng 4-6 quyên sách, khi nguời xem nháy chuột vào một quyển sách đó. Một số trang giới thiệu chi tiết sách có thể chèn một số hình ảnh chụp từ sách, có thể chèn video giới thiệu do các thành viên của câu lạc bộ tự biên tập, có thể chứa một số liên kết đến các website có bán sách đó.\n\nBan điều hành đã cùng thảo luận và đưa ra ý kiến để xây dựng website như sau:",
    "tfItems": [
      {
        "id": "a",
        "content": "Ban điều hành để có thể sử dụng phần mềm miễn phí tự xây dựng website theo yêu cầu trên.",
        "correctAnswer": true
      },
      {
        "id": "b",
        "content": "Phần mêm tạo website cho phép chèn hình ảnh là ánh bìa của sách, ảnh này có thể tải từ Internet hoặc tự chụp lại từ sách.",
        "correctAnswer": true
      },
      {
        "id": "c",
        "content": "Từ hình ảnh chèn vào các trang web, chỉ có thể tạo liên kết đến một trang trong cùng website đó, không thể chèn liên kết đến các trang bên ngoài.",
        "correctAnswer": false
      },
      {
        "id": "d",
        "content": "Khi chèn liên kết đến các webite có bán sách đang được giới thiệu,các phần mềm xây dựng website miễn phí có giới hạn về số lượng liên kết đến các website thương mại. Đồng thời, từ các liên kết này sẽ mở ra trang web bán hàng trong một thě mới của trình duyệt.",
        "correctAnswer": false
      }
    ],
    "difficulty": "ThongHieu",
    "hints": {
      "level1_concept": "Nắm vững lý thuyết xây dựng website bằng phần mềm trực quan: menu tối đa 3 cấp, header/footer đồng nhất, các khối block, form thu thập dữ liệu, hosting và tên miền.",
      "level2_formula": "Đối chiếu từng mệnh đề a, b, c, d với các nguyên tắc kỹ thuật và tính tương thích trên đa thiết bị (responsive).",
      "level3_steps": "Xác định tính Đúng / Sai của từng mệnh đề dựa trên các phát biểu chuẩn xác trong sách giáo khoa và tài liệu chuyên đề."
    },
    "explanation": "**Phân tích chi tiết từng mệnh đề cho Câu 9:**\n- **Ý a) [Đúng]**: Ban điều hành để có thể sử dụng phần mềm miễn phí tự xây dựng website theo yêu cầu trên.\n- **Ý b) [Đúng]**: Phần mêm tạo website cho phép chèn hình ảnh là ánh bìa của sách, ảnh này có thể tải từ Internet hoặc tự chụp lại từ sách.\n- **Ý c) [Sai]**: Từ hình ảnh chèn vào các trang web, chỉ có thể tạo liên kết đến một trang trong cùng website đó, không thể chèn liên kết đến các trang bên ngoài.\n- **Ý d) [Sai]**: Khi chèn liên kết đến các webite có bán sách đang được giới thiệu,các phần mềm xây dựng website miễn phí có giới hạn về số lượng liên kết đến các website thương mại. Đồng thời, từ các liên kết này sẽ mở ra trang web bán hàng trong một thě mới của trình duyệt.",
